func assertExactKeys(t *testing.T, obj map[string]json.RawMessage, want ...string) {
	t.Helper()
	expected := make(map[string]bool, len(want))
	for _, k := range want {
		expected[k] = true
		if _, ok := obj[k]; !ok {
			t.Errorf("missing JSON key %q", k)
		}
	}
	for k := range obj {
		if !expected[k] {
			t.Errorf("unexpected JSON key %q", k)
		}
	}
}

